import ms from "ms";

export function toMs(text) {
  if (typeof text !== "string" || text === "") {
    throw new TypeError(`Not a duration: ${String(text)}`);
  }
  const value = ms(text);
  if (value === undefined) throw new TypeError(`Not a duration: ${text}`);
  return value;
}
import assert from "node:assert/strict";
import { test } from "node:test";
import { toMs } from "../src/duration.mjs";

test("converts durations to milliseconds", () => {
  assert.equal(toMs("2s"), 2000);
  assert.equal(toMs("1h"), 3600000);
  assert.equal(toMs("0s"), 0);
  assert.equal(toMs("1.5s"), 1500);
  assert.equal(toMs("-2s"), -2000);
});

test("throws TypeError for non-durations", () => {
  for (const bad of ["soon", "", 5, null, undefined, {}]) {
    assert.throws(() => toMs(bad), TypeError);
  }
});
